  "{count} downloading": "{count} pobieranych",
  "{count} earlier episodes in this season are still unwatched.": "{count} wcześniejszych odcinków w tym sezonie wciąż jest nieobejrzanych.",
  "{count} earlier seasons are still unwatched.": "{count} wcześniejszych sezonów wciąż jest nieobejrzanych.",
